import {demoKey,localizedDemo,loadLocalizedDemo} from './demo-locales.js';
import {helpLabels} from './help.js';
import {episodeLabels,reconstructEpisode,episodeText} from './episode.js';
import {CATEGORIES,SOURCES,CERTAINTIES,uid,localDate,validateBackup,sortRecords,groups,inRange,linkRecords,summaryText,makeDemo,previousVersion} from './core.js';
import {LANGUAGES,chooseLanguage,languageInfo,getLabels} from './locales.js';
import {openCapture} from './capture-ui.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7M5 9v12h14V9M9 21v-7h6v7',timeline:'M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01',review:'M9 3H5a2 2 0 0 0-2 2v12a2 2 0 0 0 2 2h4M15 5h4a2 2 0 0 1 2 2v12a2 2 0 0 1-2 2h-4M9 9l3-3 3 3M12 6v12M9 15l3 3 3-3',summary:'M14 2H5v20h14V7l-5-5v5h5M8 11h8M8 15h8M8 18h5',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M19 5l-2 2M7 17l-2 2',plus:'M12 5v14M5 12h14',arrow:'M5 12h14M14 7l5 5-5 5',check:'m5 12 4 4L19 6',lock:'M6 10h12v11H6zM8 10V6a4 4 0 0 1 8 0v4',close:'m6 6 12 12M6 18 18 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',note:'M4 3h12l4 4v14H4zM8 9h8M8 13h8M8 17h5',people:'M9 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6M3 21v-4a6 6 0 0 1 12 0v4M17 4a3 3 0 0 1 0 6M19 21v-4a6 6 0 0 0-2-4',info:'M12 8h.01M12 11v6M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20'};
const icon=n=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[n]||icons.note}"/></svg>`;
const KEY='care-notes.records.v1';let lang=chooseLanguage(navigator.languages||[navigator.language]),mode='demo',view='episode',storageIssue='',rawBroken='',offlineState='offlineWait',filter={category:'',source:'',from:'',to:''},excluded=new Set(),includeAuthors=false;
try{const savedLang=localStorage.getItem('care-notes.lang');if(savedLang)lang=chooseLanguage([savedLang]);mode=localStorage.getItem('care-notes.mode')==='mine'?'mine':'demo';}catch{}
let t={...getLabels(lang),episode:episodeLabels[lang].episode};let includeUndated=true;const wrap=records=>({format:'care-notes',version:2,records});let personal=[],demo=localizedDemo(lang);
try{const raw=localStorage.getItem(KEY);if(raw){try{personal=validateBackup(JSON.parse(raw));}catch{rawBroken=raw;storageIssue='corrupt';}}try{demo=loadLocalizedDemo(localStorage,lang);}catch{}}catch{storageIssue='storageError';}
const records=()=>mode==='demo'?demo:personal;const relevant=()=>sortRecords(records().filter(r=>(!filter.category||r.category===filter.category)&&(!filter.source||r.source===filter.source)&&inRange(r,filter.from,filter.to)));
const selected=()=>relevant().filter(r=>!excluded.has(r.id));
let revision=0;
function persist(next,target=mode){if(target==='mine'&&rawBroken){toast(t.deleteBlocked);return false;}try{const serialized=JSON.stringify(wrap(next));if(new TextEncoder().encode(serialized).length>1_900_000)throw Error('storage limit');localStorage.setItem(target==='mine'?KEY:demoKey(lang),serialized);if(target==='mine')personal=next;else demo=next;revision++;storageIssue='';return true;}catch{storageIssue='storageError';toast(t.storageError);return false;}}
function pref(k,v){try{localStorage.setItem('care-notes.'+k,v);}catch{}}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
const btn=(action,text,style='line',ico='',data='')=>`<button class="btn ${style}" data-action="${action}" ${data}>${ico?icon(ico):''}${esc(text)}</button>`;
const tag=r=>`<span class="tag ${r.source}">${esc(t[r.source])}</span>`;
const stamp=r=>`${esc(r.date||t.unknownDate)}${r.time?' · '+esc(r.time):''}${r.when?' · '+esc(r.when):''}`;
function header(title,subtitle,action=''){return `<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div>${action}</div>`;}
function empty(title,hint,button=false){return `<div class="empty">${icon('note')}<h2>${esc(title)}</h2><p>${esc(hint)}</p>${button?btn('add',t.newRecord,'primary','plus'):''}</div>`;}
function entry(r){const g=groups(records()).find(g=>g.items.some(x=>x.id===r.id));return `<article class="entry"><div class="entry-top"><span>${stamp(r)}</span><span>· ${esc(t[r.category])}</span></div><div class="entry-top">${tag(r)}${r.certainty!=='direct'?`<span class="tag pending">${esc(t[r.certainty])}</span>`:''}${g?`<span class="tag ${g.pending?'pending':'noted'}">${esc(g.pending?t.pending:t.reviewed)}</span>`:''}</div><p>${esc(r.text)}</p><div class="entry-actions">${btn('edit',t.edit,'ghost','',`data-id="${esc(r.id)}"`)}${r.author?`<span class="updated">${esc(r.author)}</span>`:''}</div></article>`;}
function compare(g,full=false){return `<article class="review-feature"><div class="panel-head"><h2>${esc(t.compareTitle)}</h2><span class="tag ${g.pending?'pending':'noted'}">${esc(g.pending?t.pending:t.reviewed)}</span></div><div class="comparison">${g.items.map(r=>`<div class="quote-box ${r.source}"><div class="entry-top">${tag(r)}<span>${esc(t[r.category])} · ${esc(r.date||t.unknownDate)}</span></div><p class="quote">${esc(r.text)}</p>${full?btn('edit',t.referenceAction,'ghost','',`data-id="${esc(r.id)}"`):''}</div>`).join('')}<div class="notice">${g.items[0].reviewNote?`${esc(t.reviewNote)}：${esc(g.items[0].reviewNote)}`:esc(t.compareHint)}</div></div><div class="review-footer">${full?btn('review-note',t.markNoted,'line','',`data-id="${esc(g.id)}"`):btn('nav',t.openReview,'line','arrow','data-view="review"')}${full&&!g.pending?btn('reopen',t.reopen,'ghost','',`data-id="${esc(g.id)}"`):''}</div></article>`;}
function render(){$('.skip').textContent=({zh:'跳到内容',en:'Skip to content',es:'Ir al contenido'})[lang];t={...getLabels(lang),episode:episodeLabels[lang].episode};document.documentElement.lang=languageInfo(lang).locale;document.documentElement.dir=languageInfo(lang).direction;document.title=t.brand+' · Care Notes';const pending=groups(records()).filter(g=>g.pending).length;
$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="brand-icon">${icon('note')}</div><div><b>${esc(t.brand)}</b><small>CARE NOTES</small></div></div><nav class="nav" aria-label="${esc(t.brand)}">${['episode','timeline','summary','settings'].map(v=>`<button data-action="nav" data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(v)}<span>${esc(v==='summary'?helpLabels[lang].export:v==='settings'?helpLabels[lang].settings:t[v])}</span>${v==='review'&&pending?`<span class="count">${pending}</span>`:''}</button>`).join('')}</nav><div class="side-bottom">${icon('lock')}<p>${esc(t.local)}</p><p class="muted">${esc(t.privacy)}</p></div></aside><div class="shell"><header class="topbar"><div class="mode-picker" aria-label="${esc(t.demo)}"><button data-action="mode" data-mode="demo" class="${mode==='demo'?'active':''}" aria-pressed="${mode==='demo'}">${esc(t.demo)}</button><button data-action="mode" data-mode="mine" class="${mode==='mine'?'active':''}" aria-pressed="${mode==='mine'}">${esc(t.mine)}</button></div><div class="top-actions">${btn('help',helpLabels[lang].help,'ghost')}<span class="status">${icon('lock')} ${esc(t[offlineState])}</span><select class="lang" id="interface-language" aria-label="${esc(t.language)}">${LANGUAGES.map(l=>`<option value="${l.code}" ${lang===l.code?'selected':''}>${esc(l.label)}</option>`).join('')}</select></div></header><main id="main" class="fade">${storageIssue?`<div class="banner storage-error"><span>${esc(t[storageIssue])}</span>${rawBroken?btn('raw',t.downloadRaw,'line'):''}</div>`:''}${mode==='demo'?`<div class="banner">${icon('info')}<span>${esc(t.demoBanner)}</span>${btn('mode',t.startMine,'ghost','','data-mode="mine"')}</div>`:''}${({episode:episodePage,home:homePage,timeline:timelinePage,review:reviewPage,summary:summaryPage,settings:settingsPage}[view])()}</main></div>`;}

function episodeRelevant(){return records().filter(r=>(!filter.category||r.category===filter.category)&&(!filter.source||r.source===filter.source)&&(r.date?inRange(r,filter.from,filter.to):includeUndated));}
function episodeSelected(){return episodeRelevant().filter(r=>!excluded.has(r.id));}
function episodePage(){
 const l=episodeLabels[lang],rs=episodeRelevant(),result=reconstructEpisode(episodeSelected(),records());
 const question=q=>`<article class="paper-record"><p>${esc(l[q.kind])}</p><div class="actions">${q.refs.map(id=>btn('edit',l.edit,'line','',`data-id="${esc(id)}"`)).join('')}</div><small>${esc(q.refs.join(' · '))}</small></article>`;
 return `${header(l.episode,l.subtitle,`<div class="actions">${btn('capture',t.capture,'primary','note')}${btn('episode-export',l.handoff,'line','download')}<a class="btn line" href="./reconstruction.html?mode=own&lang=${lang}">${esc(({zh:"智能整理",en:"Organize with AI",es:"Organizar con IA",fr:"Organiser avec l’IA",ja:"AI で整理",ko:"AI로 정리"})[lang])}</a></div>`)}<details class="method-note"><summary>${esc(helpLabels[lang].details)}</summary><p>${esc(l.notice)}</p></details><details class="episode-filters"><summary>${esc(helpLabels[lang].filter)}</summary>${filters()}</details><label class="episode-undated"><input id="episode-undated" type="checkbox" ${includeUndated?'checked':''}> ${esc(l.includeUnknown)}</label><div class="summary-layout"><aside class="summary-sidebar"><section class="panel"><div class="panel-body"><h2>${esc(t.selected)} · ${result.selectedCount}</h2><p>${esc(l.scope)}</p><small>${esc(l.omitted)}: ${result.excludedCount}</small></div><div class="selection-list">${rs.map(r=>`<label><input type="checkbox" data-select="${esc(r.id)}" ${excluded.has(r.id)?'':'checked'}><span><small>${esc(r.date||l.undated)} · ${esc(t[r.source])}</small><span class="clip">${esc(r.text)}</span></span></label>`).join('')}</div></section></aside><div><section class="panel episode-questions"><div class="panel-body"><h2>${esc(l.questions)}</h2>${groups(records()).length?btn('nav',t.openReview,'ghost','','data-view="review"'):''}<p class="small muted">${esc(l.questionNotice)}</p>${result.questions.length?result.questions.slice(0,3).map(question).join(''):`<p>${esc(result.selectedCount?l.noQuestions:l.empty)}</p>`}${result.questions.length>3?`<details><summary>${esc(l.more)} (${result.questions.length-3})</summary>${result.questions.slice(3).map(question).join('')}</details>`:''}</div></section><section class="panel"><div class="panel-body"><h2>${esc(l.accounts)}</h2>${result.events.map(e=>`<article class="episode-event"><h3>${esc(e.group?l.linked:l.single)}</h3>${e.partial?`<p class="notice">${esc(l.partial)}</p>`:''}${e.items.map(r=>`<div class="paper-record"><div class="small muted">${stamp(r)} · ${esc(t[r.source])} · ${esc(t[r.certainty])}</div><p class="quote">${esc(r.text)}</p>${r.reviewNote?`<p class="notice">${esc(l.review)}: ${esc(r.reviewNote)}</p>`:''}<div class="ref">${esc(l.ref)}: ${esc(r.id)}</div>${btn('edit',l.edit,'ghost','',`data-id="${esc(r.id)}"`)}</div>`).join('')}</article>`).join('')}</div></section></div></div>`;
}

function showHelp(){
 const h=helpLabels[lang];const dlg=$('#editor');
 dlg.innerHTML=`<div class="dialog-head"><h2>${esc(h.title)}</h2>${btn('close',t.close,'ghost')}</div><div class="form-body help-body"><p>${esc(h.intro)}</p>${h.steps.map(([title,body])=>`<section><h3>${esc(title)}</h3><p>${esc(body)}</p></section>`).join('')}${['data','language','access','limits'].map(key=>`<section><h3>${esc(h[key+'Title'])}</h3><p>${esc(h[key])}</p></section>`).join('')}</div><div class="dialog-actions">${btn('help-start',h.start,'primary')}</div>`;
 if(!dlg.open)dlg.showModal();
}
function homePage(){const rs=sortRecords(records()),gs=groups(rs),p=gs.find(g=>g.pending);return `${header(t.welcome,t.homeSubtitle,`<div class="actions">${btn('capture',t.capture,'primary','note')}${btn('add',t.newRecord,'line','plus')}</div>`)}<div class="stats"><div class="stat"><div><div class="small muted">${esc(t.todayCount)}</div><div class="number">${rs.filter(r=>r.date===localDate()).length.toString().padStart(2,'0')}</div></div><div class="mini-icon">${icon('note')}</div></div><div class="stat amber"><div><div class="small muted">${esc(t.pendingCount)}</div><div class="number">${gs.filter(g=>g.pending).length.toString().padStart(2,'0')}</div></div><div class="mini-icon">${icon('review')}</div></div><div class="stat"><div><div class="small muted">${esc(t.voices)}</div><div class="number">${new Set(rs.map(r=>r.source)).size.toString().padStart(2,'0')}</div></div><div class="mini-icon">${icon('people')}</div></div></div><div class="columns"><section class="panel"><div class="panel-body"><h2>${esc(t.quick)}</h2><p class="small muted">${esc(t.quickHint)}</p><div class="quick-types">${CATEGORIES.map(c=>`<button data-action="add" data-category="${c}">${esc(t[c])}</button>`).join('')}</div></div><div class="panel-head"><h2>${esc(t.recent)}</h2>${btn('nav',t.viewAll,'ghost','','data-view="timeline"')}</div>${rs.length?`<div class="timeline">${rs.slice(0,4).map(entry).join('')}</div>`:empty(t.noRecords,t.emptyHint)}</section><aside class="aside">${p?compare(p):`<section class="panel" style="margin-bottom:20px"><div class="panel-body">${icon('check')}<h2>${esc(t.noReview)}</h2><p class="small muted">${esc(t.noReviewHint)}</p></div></section>`}<section class="aside-note"><span class="eyebrow" style="color:#c4ccff">${esc(t.nextVisit)}</span><h2>${esc(t.summaryCard)}</h2><p>${esc(t.summaryCardText)}</p>${btn('nav',t.makeSummary,'line','arrow','data-view="summary"')}</section></aside></div>`;}
function filters(){return `<div class="filters"><label>${esc(t.category)}<select data-filter="category"><option value="">${esc(t.allCategories)}</option>${CATEGORIES.map(c=>`<option value="${c}" ${filter.category===c?'selected':''}>${esc(t[c])}</option>`).join('')}</select></label><label>${esc(t.source)}<select data-filter="source"><option value="">${esc(t.allSources)}</option>${SOURCES.map(s=>`<option value="${s}" ${filter.source===s?'selected':''}>${esc(t[s])}</option>`).join('')}</select></label><label>${esc(t.from)}<input type="date" data-filter="from" value="${esc(filter.from)}"></label><label>${esc(t.to)}<input type="date" data-filter="to" value="${esc(filter.to)}"></label>${btn('reset-filter',t.clearFilter,'ghost')}</div>`;}
function timelinePage(){const rs=relevant();return `${header(t.timeline,t.timelineSubtitle,btn('add',t.newRecord,'primary','plus'))}${filters()}<section class="panel">${rs.length?`<div class="timeline">${rs.map(entry).join('')}</div>`:empty(records().length?t.noMatches:t.noRecords,records().length?t.noMatchesHint:t.emptyHint,true)}</section>`;}
function reviewPage(){const gs=groups(records()).sort((a,b)=>Number(b.pending)-Number(a.pending));return `${header(t.review,t.reviewSubtitle)}${gs.length?`<div class="review-grid">${gs.map(g=>compare(g,true)).join('')}</div>`:`<section class="panel">${empty(t.noReview,t.noReviewHint)}</section>`}`;}
function summaryPage(){const rs=relevant(),ss=selected(),gs=groups(ss);return `${header(t.summary,t.summarySubtitle,`<div class="actions">${btn('export-text',t.exportText,'line','download')}${btn('print',t.print,'primary')}</div>`)}${filters()}<div class="summary-layout"><aside class="summary-sidebar"><section class="panel"><div class="panel-head"><h2>${esc(t.selected)} <span class="muted">${ss.length}</span></h2></div><div class="panel-body"><div class="actions">${btn('select-all',t.selectAll,'ghost')}${btn('select-none',t.selectNone,'ghost')}</div><p class="small muted">${esc(t.selectionHint)}</p></div><div class="selection-list">${rs.map(r=>`<label><input type="checkbox" data-select="${esc(r.id)}" ${excluded.has(r.id)?'':'checked'}><span><small>${esc(r.date||t.unknownDate)} · ${esc(t[r.source])}</small><span class="clip">${esc(r.text)}</span></span></label>`).join('')}</div><div class="panel-body"><label class="small"><input type="checkbox" id="authors" ${includeAuthors?'checked':''}> ${esc(t.includeAuthors)}</label></div></section></aside><section class="paper" aria-label="${esc(t.summaryTitle)}"><span class="eyebrow">CARE NOTES / ${esc(t.visitBrief)}</span><h2 class="paper-title">${esc(t.summaryTitle)}</h2><div class="paper-meta">${mode==='demo'?`<p>${esc(t.demoLabel)}</p>`:''}${esc(t.generated)}：${esc(new Date().toLocaleString(t.locale))}<br>${esc(t.range)}：${esc(filter.from||t.unlimited)} — ${esc(filter.to||t.unlimited)}</div><p class="notice">${esc(t.summaryNotice)}</p>${ss.length?ss.map((r,i)=>{const g=gs.find(g=>g.items.some(x=>x.id===r.id));return `<article class="paper-record"><h3>[${i+1}] ${stamp(r)} · ${esc(t[r.category])}</h3><div class="small muted">${esc(t[r.source])}${includeAuthors&&r.author?' · '+esc(r.author):''} · ${esc(t[r.certainty])}</div><p class="summary-text">${esc(r.text)}</p>${g?`<div class="notice">${esc(g.pending?t.pending:t.noted)}${r.reviewNote?' · '+esc(r.reviewNote):''}</div>`:r.group?`<div class="notice">${esc(t.relatedOutside)}</div>`:''}<div class="ref">${esc(t.reference)}：${esc(r.id)}<br>${esc(t.updated)}：${esc(r.updatedAt)}</div>${btn('edit',t.referenceAction,'ghost','',`data-id="${esc(r.id)}"`)}</article>`;}).join(''):empty(t.emptySummary,t.previewHint)}<p class="notice">${esc(t.missingNotice)}</p></section></div>`;}
function settingsPage(){return `${header(t.settings,t.settingsSubtitle)}<div class="settings-stack"><section class="panel"><div class="settings-row"><div><h2>${esc(t.language)}</h2><p>${esc(t.languageHelp)}</p></div></div></section><section class="panel"><div class="settings-row"><div><span class="pill">${esc(t.local)}</span><h2>${esc(t.storageTitle)}</h2><p>${esc(t.storageDesc)}</p></div></div><div class="settings-row"><div><h2>${esc(t.backupTitle)}</h2><p>${esc(t.backupDesc)}</p></div><div class="actions">${btn('backup',t.backup,'line','download')}${btn('restore',t.restore,'primary')}</div><input type="file" id="backup-file" accept="application/json,.json" hidden></div></section><section class="panel"><div class="settings-row"><div><h2>${esc(t.installTitle)}</h2><p>${esc(t.installDesc)}</p><p>${esc(t[offlineState])} · ${esc(t.offlineDesc)}</p></div></div><div class="settings-row"><div><h2>${esc(t.demoTitle)}</h2><p>${esc(t.demoDesc)}</p></div>${btn('reset-demo',t.resetDemo,'line')}</div></section><section class="panel"><div class="settings-row"><div><h2>${esc(t.clearTitle)}</h2><p>${esc(t.clearDesc)}</p></div>${btn('clear',t.clear,'danger')}</div></section><div class="small muted"><b>${esc(t.aboutTitle)}</b><p>${esc(t.aboutDesc)}</p></div></div>`;}
function showEditor(id='',category='other'){
 const r=records().find(r=>r.id===id);if(id&&!r){toast(t.recordMissing);return;}const snapshot=revision;const rs=records().filter(x=>x.id!==id);const existingRelated=r?.group?rs.find(x=>x.group===r.group)?.id:'';
 const field=(label,name,value='',type='text',extra='')=>`<label class="field">${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
 const select=(label,name,values,value)=>`<label class="field">${esc(label)}<select name="${name}">${values.map(x=>`<option value="${x}" ${x===value?'selected':''}>${esc(t[x])}</option>`).join('')}</select></label>`;
 $('#editor').innerHTML=`<form id="record-form"><div class="dialog-head"><h2>${esc(r?t.editTitle:t.addTitle)}</h2><button type="button" class="close" data-action="close" aria-label="${esc(t.close)}">${icon('close')}</button></div><div class="form-body">${mode==='demo'?`<span class="pill">${esc(t.demoLabel)}</span>`:''}<div class="form-grid">${select(t.category,'category',CATEGORIES,r?.category||category)}${select(t.source,'source',SOURCES,r?.source||'family')}${field(t.eventDate,'date',r?r.date:localDate(),'date')}${field(t.eventTime,'time',r?.time||'','time')}</div><label class="field" style="margin-top:16px">${esc(t.when)}<input name="when" maxlength="120" placeholder="${esc(t.whenPlaceholder)}" value="${esc(r?.when||'')}"></label><label class="field">${esc(t.text)}<textarea name="text" maxlength="5000" required placeholder="${esc(t.textPlaceholder)}">${esc(r?.text||'')}</textarea><small>${esc(t.charHint)}</small></label><div class="form-grid">${select(t.certainty,'certainty',CERTAINTIES,r?.certainty||'direct')}${field(t.author,'author',r?.author||'','text',`maxlength="60" placeholder="${esc(t.authorPlaceholder)}"`)}</div><label class="field" style="margin-top:16px">${esc(t.related)}<select name="related"><option value="">${esc(t.noRelated)}</option>${rs.map(x=>`<option value="${esc(x.id)}" ${existingRelated===x.id?'selected':''}>${esc(x.date||t.unknownDate)} · ${esc(t[x.source])} · ${esc(x.text.slice(0,50))}</option>`).join('')}</select><small>${esc(t.relatedHelp)}</small></label>${r?.provenance?`<details class="notice"><summary>${esc(t.captureEvidence)}</summary><p>${esc(t.captureProvenanceHelp)}</p><blockquote class="quote">${esc(r.provenance.original)}</blockquote><p>${esc(t.captureMethod)}: ${esc(r.provenance.method==='openai'?t.captureAI:t.captureLocal)} · ${esc(t.captureSpan)}: ${r.provenance.start}–${r.provenance.end}</p></details>`:''}${r?`<div class="small muted">${esc(t.savedAt)}：${esc(new Date(r.createdAt).toLocaleString(t.locale))}<br>${esc(t.updated)}：${esc(new Date(r.updatedAt).toLocaleString(t.locale))}</div>${r.group?`<p class="notice">${esc(t.corrected)}</p>`:''}${r.history?.length?`<details class="notice"><summary>${esc(t.previousVersions)} (${r.history.length})</summary>${[...r.history].reverse().map(h=>`<div class="paper-record"><span class="small">${esc(h.updatedAt)} · ${esc(t[h.source])}</span><p class="quote">${esc(h.text)}</p></div>`).join('')}</details>`:''}`:''}</div><div class="dialog-actions">${r?btn('delete',t.delete,'danger','',`type="button" data-id="${esc(r.id)}"`):''}<button class="btn line" type="button" data-action="close">${esc(t.cancel)}</button><button class="btn primary" type="submit">${esc(t.save)}</button></div></form>`;
 const dlg=$('#editor');if(!dlg.open)dlg.showModal();
 $('#record-form').onsubmit=e=>{e.preventDefault();if(snapshot!==revision){toast(t.conflict);return;}const fd=new FormData(e.target);const now=new Date().toISOString();const note={id:r?.id||uid(),category:fd.get('category'),source:fd.get('source'),date:fd.get('date'),time:fd.get('time'),when:fd.get('when').trim(),text:fd.get('text').trim(),certainty:fd.get('certainty'),author:fd.get('author').trim(),group:r?.group||'',review:'pending',reviewNote:'',createdAt:r?.createdAt||now,updatedAt:now,history:r?[...(r.history||[]),previousVersion(r)]:[],...(r?.provenance?{provenance:r.provenance}:{})};if(!note.text){e.target.elements.text.setCustomValidity(t.textPlaceholder);e.target.elements.text.reportValidity();e.target.elements.text.oninput=()=>e.target.elements.text.setCustomValidity('');return;}
 let next=linkRecords(records(),note,fd.get('related'));try{next=validateBackup(wrap(next));}catch{toast(t.invalidBackup);return;}if(persist(next)){dlg.close();render();toast(t.saveSuccess);}};
}
function confirmAction(title,body,action){const dlg=$('#confirm');dlg.innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2><button class="close" data-action="confirm-close" aria-label="${esc(t.close)}">${icon('close')}</button></div><div class="form-body"><p>${esc(body)}</p></div><div class="dialog-actions"><button class="btn line" data-action="confirm-close">${esc(t.cancel)}</button><button class="btn primary" id="confirmed">${esc(t.confirm)}</button></div>`;if(!dlg.open)dlg.showModal();$('#confirmed').onclick=()=>{dlg.close();action();};}
function reviewEditor(id){const g=groups(records()).find(g=>g.id===id);if(!g)return;const snapshot=revision;const dlg=$('#editor');dlg.innerHTML=`<form id="review-form"><div class="dialog-head"><h2>${esc(t.reviewNote)}</h2><button type="button" class="close" data-action="close" aria-label="${esc(t.close)}">${icon('close')}</button></div><div class="form-body"><label class="field">${esc(t.reviewNote)}<textarea name="note" maxlength="1000" required placeholder="${esc(t.reviewPlaceholder)}">${esc(g.items[0].reviewNote)}</textarea></label><p class="notice">${esc(t.reviewHelp)}</p></div><div class="dialog-actions"><button class="btn line" type="button" data-action="close">${esc(t.cancel)}</button><button class="btn primary" type="submit">${esc(t.saveReview)}</button></div></form>`;dlg.showModal();$('#review-form').onsubmit=e=>{e.preventDefault();if(snapshot!==revision){toast(t.conflict);return;}const note=new FormData(e.target).get('note').trim();if(!note){toast(t.noteRequired);return;}const next=records().map(r=>r.group===id?{...r,review:'noted',reviewNote:note,updatedAt:new Date().toISOString()}:r);if(persist(next)){dlg.close();render();toast(t.reviewSuccess);}};}
function download(name,content,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);toast(t.exported);}
function navigate(v){view=v;filter={category:'',source:'',from:'',to:''};excluded.clear();render();window.scrollTo(0,0);}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const {action,id}=el.dataset;
 switch(action){case 'help':showHelp();break;case 'help-start':$('#editor').close();navigate('episode');break;case 'episode-export':if(!episodeSelected().length){toast(t.noExport);break;}download(`care-notes-episode-${localDate()}.txt`,episodeText(reconstructEpisode(episodeSelected(),records()),episodeLabels[lang],t,{demo:mode==='demo'}));break;case 'nav':navigate(el.dataset.view);break;case 'mode':mode=el.dataset.mode;pref('mode',mode);revision++;excluded.clear();filter={category:'',source:'',from:'',to:''};render();break;case 'capture':openCapture({dialog:$('#editor'),labels:t,revision,getRevision:()=>revision,onSave:notes=>{if(!persist([...records(),...notes]))return false;render();return true;},toast});break;case 'add':showEditor('',el.dataset.category||'other');break;case 'edit':showEditor(id);break;case 'close':$('#editor').close();break;case 'confirm-close':$('#confirm').close();break;case 'delete':confirmAction(t.confirmDelete,t.confirmDeleteText,()=>{const old=records().find(r=>r.id===id);const next=records().filter(r=>r.id!==id).map(r=>old?.group&&r.group===old.group?{...r,review:'pending',reviewNote:''}:r);if(persist(next)){$('#editor').close();render();toast(t.deleted);}});break;case 'review-note':reviewEditor(id);break;case 'reopen':if(persist(records().map(r=>r.group===id?{...r,review:'pending',reviewNote:'',updatedAt:new Date().toISOString()}:r))){render();}break;case 'reset-filter':filter={category:'',source:'',from:'',to:''};render();break;case 'select-all':excluded.clear();render();break;case 'select-none':relevant().forEach(r=>excluded.add(r.id));render();break;case 'export-text':if(!selected().length){toast(t.noExport);break;}download(`care-notes-summary-${localDate()}.txt`,summaryText(selected(),t,{demo:mode==='demo',includeAuthors,from:filter.from,to:filter.to}));break;case 'print':if(!selected().length){toast(t.noExport);break;}window.print();break;case 'backup':if(mode==='demo'){toast(t.demoBackup);break;}download(`care-notes-backup-${localDate()}.json`,JSON.stringify({...wrap(personal),demo:false,exportedAt:new Date().toISOString()},null,2),'application/json');break;case 'restore':$('#backup-file').click();break;case 'clear':confirmAction(t.confirmClear,t.confirmClearText,()=>{if(persist([],'mine')){mode='mine';pref('mode',mode);render();toast(t.cleared);}});break;case 'reset-demo':if(persist(localizedDemo(lang),'demo')){mode='demo';pref('mode',mode);render();toast(t.resetDone);}break;case 'raw':download(`care-notes-recovery-${localDate()}.txt`,rawBroken);break;}
});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='episode-undated'){includeUndated=el.checked;render();return;}if(el.id==='interface-language'){lang=chooseLanguage([el.value]);pref('lang',lang);try{demo=loadLocalizedDemo(localStorage,lang);}catch{demo=localizedDemo(lang);}revision++;excluded.clear();render();return;}if(el.dataset.filter){const key=el.dataset.filter,value=el.value;const next={...filter,[key]:value};if(next.from&&next.to&&next.from>next.to){toast(t.dateError);el.value=filter[key];return;}filter=next;render();}if(el.dataset.select){el.checked?excluded.delete(el.dataset.select):excluded.add(el.dataset.select);render();}if(el.id==='authors'){includeAuthors=el.checked;render();}if(el.id==='backup-file'){const file=el.files[0];if(!file)return;try{if(file.size>2_000_000)throw Error();const data=JSON.parse(await file.text());if(data.demo){toast(t.demoImport);return;}const next=validateBackup(data);confirmAction(t.confirmRestore,t.confirmRestoreText.replace('{n}',next.length),()=>{if(persist(next,'mine')){mode='mine';pref('mode',mode);excluded.clear();render();toast(t.restored);}});}catch{toast(t.invalidBackup);}finally{el.value='';}}});
window.addEventListener('storage',e=>{if(e.key!==KEY&&e.key!==demoKey(lang))return;revision++;try{const data=e.newValue?validateBackup(JSON.parse(e.newValue)):[];if(e.key===KEY)personal=data;else demo=data;render();}catch{storageIssue='corrupt';if(e.key===KEY)rawBroken=e.newValue||'';render();}});
render();
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(()=>navigator.serviceWorker.ready).then(()=>{offlineState='offline';render();}).catch(()=>{offlineState='offlineUnavailable';render();});}else{offlineState='offlineUnavailable';render();}

